# Better extraction function
def extract_all_shapes(grid):
    """Extract all shapes with their minimal bounding boxes"""
    colors = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    shapes = {}
    for color in sorted(colors):
        positions = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    positions.append((r,c))

        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

        # Extract bbox
        shape = [[grid[r][c] for c in range(min_c, max_c+1)] for r in range(min_r, max_r+1)]
        shapes[color] = (min_r, min_c, shape)  # store with anchor position

    return shapes

