# Fix: flatten the gap columns from [0] to just 0
def solve(grid):
    colors = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    shapes = {}
    for color in sorted(colors):
        positions = [(r,c) for r in range(len(grid)) 
                     for c in range(len(grid[0])) 
                     if grid[r][c] == color]

        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

        shape = [[grid[r][c] for c in range(min_c, max_c+1)] 
                 for r in range(min_r, max_r+1)]
        shapes[color] = shape

    sorted_colors = sorted(shapes.keys())
    num_rows = len(shapes[sorted_colors[0]])

    output = []
    for r in range(num_rows):
        joined = []
        for i, c in enumerate(sorted_colors):
            if i > 0:
                joined.append(0)  # single integer gap, not [0]
            joined.extend(shapes[c][r])
        output.append(joined)

    return output

