def solve_fill_interiors(grid):
    # Find all colors
    colors = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    shapes = []
    for color in colors:
        positions = [(r,c) for r in range(len(grid)) 
                     for c in range(len(grid[0])) 
                     if grid[r][c] == color]

        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

        shape = [[grid[r][c] for c in range(min_c, max_c+1)] 
                 for r in range(min_r, max_r+1)]

        # Fill any 0s inside the bbox with the color
        for r in range(len(shape)):
            for c in range(len(shape[r])):
                if shape[r][c] == 0:
                    shape[r][c] = color

        shapes.append((min_c, color, shape))

    shapes.sort(key=lambda x: x[0])

    num_rows = len(shapes[0][2])
    output = []
    for r in range(num_rows):
        joined = []
        for i, (_, color, shape) in enumerate(shapes):
            if i > 0:
                joined.append(0)  # gap
            joined.extend(shape[r])
        output.append(joined)

    return output

